-- SANOR QUEST · complete database setup for a NEW Supabase project (generated by `npm run build`; do not edit).
-- Paste all of it into Supabase → SQL Editor → Run. Files: 20261126000000_classroom.sql, 20261127000000_privacy.sql, 20261128000000_pilot.sql, 20261129000000_worlds.sql, 20261130000000_launch.sql

-- ================================================================ 20261126000000_classroom.sql
-- SANOR QUEST · classroom backend (Supabase / Postgres 15+)
--
-- Who can do what
--   * Teachers sign in with Supabase Auth (email + password). Row level security lets a teacher read only
--     the classes they own and the students, progress, answers and tests inside those classes.
--   * Students have no account and no email. They join with a class code + class number + nickname + 4-digit PIN
--     (join_class). They get a random session token and can only write their own data through
--     submit_events(token, …). The anon role has no direct access to any table.
--   * PINs are stored as salted SHA-256 hashes. Five wrong PINs lock that student for 10 minutes.
--
-- Data we keep about students (PDPA): class number, a nickname they choose, PIN hash, game progress,
-- answers, speaking self-checks and test scores. No real names, emails, photos or recordings.

-- ---------------------------------------------------------------- tables
create table public.teachers (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text not null default '' check (length(display_name) <= 80),
  school text not null default '' check (length(school) <= 120),
  created_at timestamptz not null default now()
);

create table public.classes (
  id uuid primary key default gen_random_uuid(),
  teacher_id uuid not null references public.teachers(id) on delete cascade,
  name text not null check (length(name) between 1 and 60),
  code text not null unique check (code ~ '^[A-Z0-9]{6}$'),
  worlds_open text[] not null default '{01,02}',
  thai_level text check (thai_level in ('starter','explorer','challenger')),   -- null = each student chooses
  tests_open text[] not null default '{pre}' check (tests_open <@ array['pre','post']),
  created_at timestamptz not null default now()
);

create table public.students (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references public.classes(id) on delete cascade,
  number int not null check (number between 1 and 99),
  nickname text not null check (length(nickname) between 1 and 20),
  pin_salt text not null,
  pin_hash text not null,
  failed_logins int not null default 0,
  locked_until timestamptz,
  created_at timestamptz not null default now(),
  last_seen timestamptz,
  unique (class_id, number)
);

create table public.sessions (
  token_hash text primary key,
  student_id uuid not null references public.students(id) on delete cascade,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null
);

-- best progress per activity (XP never goes down; done stays done)
create table public.progress (
  student_id uuid not null references public.students(id) on delete cascade,
  world text not null check (world ~ '^[a-z0-9]{1,12}$'),
  activity text not null check (activity ~ '^[a-z0-9-]{1,24}$'),
  xp int not null default 0 check (xp between 0 and 5000),
  done boolean not null default false,
  stamps int not null default 0 check (stamps between 0 and 200),
  updated_at timestamptz not null default now(),
  primary key (student_id, world, activity)
);

-- every first answer, speaking result and test, as sent by the game (client_id makes re-sending safe)
create table public.events (
  id bigint generated always as identity primary key,
  student_id uuid not null references public.students(id) on delete cascade,
  class_id uuid not null references public.classes(id) on delete cascade,
  client_id text not null check (length(client_id) between 8 and 64),
  kind text not null check (kind in ('answer','speech')),
  world text not null default '' check (length(world) <= 12),
  activity text not null default '' check (length(activity) <= 24),
  item text not null default '' check (length(item) <= 64),
  label text not null default '' check (length(label) <= 160),
  correct boolean,
  first_try boolean,
  hint boolean,
  result text check (result is null or result in ('asr','self','not-yet','skip')),
  client_at timestamptz,
  created_at timestamptz not null default now(),
  unique (student_id, client_id)
);
create index events_class_idx on public.events (class_id, kind);

create table public.tests (
  student_id uuid not null references public.students(id) on delete cascade,
  kind text not null check (kind in ('pre','post')),
  score int not null check (score >= 0),
  total int not null check (total > 0 and score <= total),
  answers jsonb not null default '[]',
  taken_at timestamptz not null default now(),
  primary key (student_id, kind)
);

-- ---------------------------------------------------------------- row level security
alter table public.teachers enable row level security;
alter table public.classes  enable row level security;
alter table public.students enable row level security;
alter table public.sessions enable row level security;
alter table public.progress enable row level security;
alter table public.events   enable row level security;
alter table public.tests    enable row level security;

revoke all on public.teachers, public.classes, public.students, public.sessions, public.progress, public.events, public.tests from anon;
grant select, insert, update on public.teachers to authenticated;
grant select, update, delete on public.classes to authenticated;
grant select, delete on public.students to authenticated;
grant select on public.progress, public.events, public.tests to authenticated;
revoke all on public.sessions from authenticated;

create policy "teacher: own profile" on public.teachers for all to authenticated
  using (id = auth.uid()) with check (id = auth.uid());
create policy "teacher: own classes" on public.classes for all to authenticated
  using (teacher_id = auth.uid()) with check (teacher_id = auth.uid());
create policy "teacher: students in own classes" on public.students for all to authenticated
  using (exists (select 1 from public.classes c where c.id = class_id and c.teacher_id = auth.uid()));
create policy "teacher: progress in own classes" on public.progress for select to authenticated
  using (exists (select 1 from public.students s join public.classes c on c.id = s.class_id where s.id = student_id and c.teacher_id = auth.uid()));
create policy "teacher: answers in own classes" on public.events for select to authenticated
  using (exists (select 1 from public.classes c where c.id = class_id and c.teacher_id = auth.uid()));
create policy "teacher: tests in own classes" on public.tests for select to authenticated
  using (exists (select 1 from public.students s join public.classes c on c.id = s.class_id where s.id = student_id and c.teacher_id = auth.uid()));

-- ---------------------------------------------------------------- helpers
create or replace function public.sq_hash(salt text, secret text) returns text
  language sql immutable set search_path = public, pg_temp
  as $$ select encode(sha256(convert_to(salt || ':' || secret, 'UTF8')), 'hex') $$;

create or replace function public.sq_student(p_token text) returns public.students
  language plpgsql security definer set search_path = public, pg_temp as $$
declare s public.students;
begin
  select st.* into s from public.sessions se join public.students st on st.id = se.student_id
   where se.token_hash = public.sq_hash('session', coalesce(p_token,'')) and se.expires_at > now();
  if not found then raise exception 'bad_token' using errcode = 'P0001'; end if;
  return s;
end $$;

create or replace function public.sq_settings(c public.classes) returns jsonb
  language sql stable set search_path = public, pg_temp as $$
  select jsonb_build_object('className', c.name, 'code', c.code, 'worldsOpen', to_jsonb(c.worlds_open),
                            'thaiLevel', c.thai_level, 'testsOpen', to_jsonb(c.tests_open)) $$;

create or replace function public.sq_own_class(p_class uuid) returns void
  language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if auth.uid() is null or not exists (select 1 from public.classes where id = p_class and teacher_id = auth.uid()) then
    raise exception 'not_your_class' using errcode = 'P0001';
  end if;
end $$;

-- ---------------------------------------------------------------- student functions (anon)
-- Join a class (first time) or sign in again (same class number + PIN). Returns a session token.
create or replace function public.join_class(p_code text, p_number int, p_nickname text, p_pin text) returns jsonb
  language plpgsql security definer set search_path = public, pg_temp as $$
declare c public.classes; s public.students; tok text; nick text := btrim(coalesce(p_nickname,''));
begin
  if coalesce(p_pin,'') !~ '^[0-9]{4}$' then raise exception 'bad_pin_format' using errcode = 'P0001'; end if;
  if p_number is null or p_number not between 1 and 99 then raise exception 'bad_number' using errcode = 'P0001'; end if;
  select * into c from public.classes where code = upper(btrim(coalesce(p_code,'')));
  if not found then raise exception 'class_not_found' using errcode = 'P0001'; end if;
  select * into s from public.students where class_id = c.id and number = p_number for update;
  if found then
    if s.locked_until is not null and s.locked_until > now() then raise exception 'locked' using errcode = 'P0001'; end if;
    if s.pin_hash <> public.sq_hash(s.pin_salt, p_pin) then
      update public.students set failed_logins = failed_logins + 1,
             locked_until = case when failed_logins + 1 >= 5 then now() + interval '10 minutes' else null end
       where id = s.id;
      return jsonb_build_object('error', case when s.failed_logins + 1 >= 5 then 'locked' else 'wrong_pin' end);
    end if;
    update public.students set failed_logins = 0, locked_until = null, last_seen = now() where id = s.id returning * into s;
  else
    if length(nick) not between 1 and 20 then raise exception 'bad_nickname' using errcode = 'P0001'; end if;
    insert into public.students (class_id, number, nickname, pin_salt, pin_hash, last_seen)
    values (c.id, p_number, nick, gen_random_uuid()::text, '', now()) returning * into s;
    update public.students set pin_hash = public.sq_hash(s.pin_salt, p_pin) where id = s.id;
  end if;
  tok := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  insert into public.sessions (token_hash, student_id, expires_at) values (public.sq_hash('session', tok), s.id, now() + interval '180 days');
  return jsonb_build_object('token', tok, 'student', jsonb_build_object('number', s.number, 'nickname', s.nickname), 'settings', public.sq_settings(c));
end $$;

-- Current class settings (worlds open, Thai-help level, tests open).
create or replace function public.class_settings(p_token text) returns jsonb
  language plpgsql security definer set search_path = public, pg_temp as $$
declare s public.students; c public.classes;
begin
  s := public.sq_student(p_token);
  select * into c from public.classes where id = s.class_id;
  update public.students set last_seen = now() where id = s.id;
  return public.sq_settings(c);
end $$;

-- Upload a batch from the game's outbox. Safe to send twice (client_id). Returns how many were new.
create or replace function public.submit_events(p_token text, p_events jsonb) returns int
  language plpgsql security definer set search_path = public, pg_temp as $$
declare s public.students; e jsonb; n int := 0; k text; got int;
begin
  s := public.sq_student(p_token);
  if jsonb_typeof(p_events) <> 'array' or jsonb_array_length(p_events) > 200 then raise exception 'bad_batch' using errcode = 'P0001'; end if;
  for e in select * from jsonb_array_elements(p_events) loop
    k := e->>'kind';
    if k in ('answer','speech') then
      insert into public.events (student_id, class_id, client_id, kind, world, activity, item, label, correct, first_try, hint, result, client_at)
      values (s.id, s.class_id, left(e->>'id', 64), k, left(coalesce(e->>'world',''),12), left(coalesce(e->>'activity',''),24),
              left(coalesce(e->>'item',''),64), left(coalesce(e->>'label',''),160),
              (e->>'correct')::boolean, (e->>'firstTry')::boolean, (e->>'hint')::boolean,
              case when e->>'result' in ('asr','self','not-yet','skip') then e->>'result' end,
              least(now(), coalesce((e->>'at')::timestamptz, now())))
      on conflict (student_id, client_id) do nothing;
      get diagnostics got = row_count; n := n + got;
    elsif k = 'progress' then
      insert into public.progress (student_id, world, activity, xp, done, stamps)
      values (s.id, e->>'world', e->>'activity', least(5000, greatest(0, coalesce((e->>'xp')::int,0))), coalesce((e->>'done')::boolean,false), least(200, greatest(0, coalesce((e->>'stamps')::int,0))))
      on conflict (student_id, world, activity) do update
        set xp = greatest(progress.xp, excluded.xp), done = progress.done or excluded.done,
            stamps = greatest(progress.stamps, excluded.stamps), updated_at = now();
      n := n + 1;
    elsif k = 'test' and e->>'test' in ('pre','post') then
      insert into public.tests (student_id, kind, score, total, answers)
      values (s.id, e->>'test', (e->>'score')::int, (e->>'total')::int, coalesce(e->'answers','[]'::jsonb))
      on conflict (student_id, kind) do nothing;          -- the first attempt is the one that counts
      get diagnostics got = row_count; n := n + got;
    end if;
  end loop;
  update public.students set last_seen = now() where id = s.id;
  return n;
end $$;

-- ---------------------------------------------------------------- teacher functions (authenticated)
create or replace function public.ensure_teacher(p_name text, p_school text) returns void
  language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if auth.uid() is null then raise exception 'not_signed_in' using errcode = 'P0001'; end if;
  insert into public.teachers (id, display_name, school) values (auth.uid(), left(coalesce(p_name,''),80), left(coalesce(p_school,''),120))
  on conflict (id) do update set display_name = case when excluded.display_name <> '' then excluded.display_name else teachers.display_name end,
                                 school = case when excluded.school <> '' then excluded.school else teachers.school end;
end $$;

create or replace function public.create_class(p_name text) returns jsonb
  language plpgsql security definer set search_path = public, pg_temp as $$
declare c public.classes; new_code text; tries int := 0;
begin
  if auth.uid() is null or not exists (select 1 from public.teachers where id = auth.uid()) then raise exception 'not_signed_in' using errcode = 'P0001'; end if;
  loop   -- 6 characters without look-alikes (no 0/O, 1/I)
    new_code := (select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', 1 + floor(random()*32)::int, 1), '') from generate_series(1,6));
    exit when not exists (select 1 from public.classes where code = new_code);
    tries := tries + 1; if tries > 20 then raise exception 'no_code' using errcode = 'P0001'; end if;
  end loop;
  insert into public.classes (teacher_id, name, code) values (auth.uid(), btrim(p_name), new_code) returning * into c;
  return jsonb_build_object('id', c.id) || public.sq_settings(c);
end $$;

create or replace function public.my_classes() returns jsonb
  language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'students', (select count(*) from public.students s where s.class_id = c.id)) || public.sq_settings(c) order by c.created_at), '[]')
    from public.classes c where c.teacher_id = auth.uid() $$;

create or replace function public.update_class(p_class uuid, p_name text, p_worlds text[], p_thai text, p_tests text[]) returns jsonb
  language plpgsql security definer set search_path = public, pg_temp as $$
declare c public.classes;
begin
  perform public.sq_own_class(p_class);
  update public.classes set name = coalesce(nullif(btrim(p_name),''), name), worlds_open = coalesce(p_worlds, worlds_open),
         thai_level = case when p_thai in ('starter','explorer','challenger') then p_thai else null end,
         tests_open = coalesce(p_tests, tests_open)
   where id = p_class returning * into c;
  return jsonb_build_object('id', c.id) || public.sq_settings(c);
end $$;

-- Everything the dashboard needs for one class, in one call.
create or replace function public.class_report(p_class uuid) returns jsonb
  language plpgsql stable security definer set search_path = public, pg_temp as $$
declare out jsonb;
begin
  perform public.sq_own_class(p_class);
  select jsonb_build_object(
    'class', (select jsonb_build_object('id', c.id) || public.sq_settings(c) from public.classes c where c.id = p_class),
    'students', coalesce((select jsonb_agg(jsonb_build_object(
        'id', s.id, 'number', s.number, 'nickname', s.nickname, 'lastSeen', s.last_seen, 'locked', s.locked_until > now(),
        'xp', coalesce((select sum(p.xp) from public.progress p where p.student_id = s.id), 0),
        'progress', coalesce((select jsonb_agg(jsonb_build_object('world', p.world, 'activity', p.activity, 'xp', p.xp, 'done', p.done)) from public.progress p where p.student_id = s.id), '[]'),
        'answers', (select count(*) from public.events e where e.student_id = s.id and e.kind = 'answer'),
        'firstTry', (select count(*) from public.events e where e.student_id = s.id and e.kind = 'answer' and e.first_try),
        'hints', (select count(*) from public.events e where e.student_id = s.id and e.kind = 'answer' and e.hint),
        'spoken', (select count(*) from public.events e where e.student_id = s.id and e.kind = 'speech' and e.result in ('asr','self')),
        'pre', (select jsonb_build_object('score', t.score, 'total', t.total) from public.tests t where t.student_id = s.id and t.kind = 'pre'),
        'post', (select jsonb_build_object('score', t.score, 'total', t.total) from public.tests t where t.student_id = s.id and t.kind = 'post')
      ) order by s.number) from public.students s where s.class_id = p_class), '[]'),
    'missed', coalesce((select jsonb_agg(m) from (
        select jsonb_build_object('item', e.item, 'label', max(e.label), 'world', max(e.world), 'missed', count(*) filter (where not e.first_try), 'tries', count(*)) as m
          from public.events e where e.class_id = p_class and e.kind = 'answer' and e.item <> ''
         group by e.item having count(*) filter (where not e.first_try) > 0
         order by count(*) filter (where not e.first_try) desc, e.item limit 10) x), '[]')
  ) into out;
  return out;
end $$;

create or replace function public.student_detail(p_student uuid) returns jsonb
  language plpgsql stable security definer set search_path = public, pg_temp as $$
declare s public.students;
begin
  select * into s from public.students where id = p_student;
  if not found then raise exception 'not_your_class' using errcode = 'P0001'; end if;
  perform public.sq_own_class(s.class_id);
  return jsonb_build_object('number', s.number, 'nickname', s.nickname,
    'events', coalesce((select jsonb_agg(jsonb_build_object('kind', e.kind, 'world', e.world, 'activity', e.activity, 'item', e.item, 'label', e.label,
                 'correct', e.correct, 'firstTry', e.first_try, 'hint', e.hint, 'result', e.result, 'at', coalesce(e.client_at, e.created_at)) order by e.id desc)
               from (select * from public.events where student_id = s.id order by id desc limit 500) e), '[]'),
    'tests', coalesce((select jsonb_agg(jsonb_build_object('kind', t.kind, 'score', t.score, 'total', t.total, 'answers', t.answers, 'at', t.taken_at)) from public.tests t where t.student_id = s.id), '[]'));
end $$;

create or replace function public.reset_student_pin(p_student uuid, p_pin text) returns void
  language plpgsql security definer set search_path = public, pg_temp as $$
declare s public.students;
begin
  if coalesce(p_pin,'') !~ '^[0-9]{4}$' then raise exception 'bad_pin_format' using errcode = 'P0001'; end if;
  select * into s from public.students where id = p_student;
  if not found then raise exception 'not_your_class' using errcode = 'P0001'; end if;
  perform public.sq_own_class(s.class_id);
  update public.students set pin_hash = public.sq_hash(pin_salt, p_pin), failed_logins = 0, locked_until = null where id = s.id;
  delete from public.sessions where student_id = s.id;   -- old devices must sign in again
end $$;

create or replace function public.remove_student(p_student uuid) returns void
  language plpgsql security definer set search_path = public, pg_temp as $$
declare s public.students;
begin
  select * into s from public.students where id = p_student;
  if not found then return; end if;
  perform public.sq_own_class(s.class_id);
  delete from public.students where id = s.id;           -- cascades to sessions, progress, events, tests
end $$;

-- ---------------------------------------------------------------- who may call what
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on function public.join_class(text,int,text,text), public.class_settings(text), public.submit_events(text,jsonb) to anon, authenticated;
grant execute on function public.ensure_teacher(text,text), public.create_class(text), public.my_classes(), public.update_class(uuid,text,text[],text,text[]),
  public.class_report(uuid), public.student_detail(uuid), public.reset_student_pin(uuid,text), public.remove_student(uuid) to authenticated;

-- ================================================================ 20261127000000_privacy.sql
-- SANOR QUEST · privacy (PDPA): a student can delete everything stored about them, and a teacher can delete a
-- whole class at the end of the school year. Deleting cascades to sessions, progress, answers and tests.

create or replace function public.delete_me(p_token text) returns void
  language plpgsql security definer set search_path = public, pg_temp as $$
declare s public.students;
begin
  s := public.sq_student(p_token);
  delete from public.students where id = s.id;
end $$;

create or replace function public.delete_class(p_class uuid) returns void
  language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public.sq_own_class(p_class);
  delete from public.classes where id = p_class;
end $$;

revoke execute on function public.delete_me(text), public.delete_class(uuid) from public, anon, authenticated;
grant execute on function public.delete_me(text) to anon, authenticated;
grant execute on function public.delete_class(uuid) to authenticated;

-- ================================================================ 20261128000000_pilot.sql
-- SANOR QUEST · classroom pilot data (Phase 7)
--   * play time: the game sends active seconds (screen visible and the student doing something) per activity
--   * steps: a question/stage was opened or finished → where students get stuck or stop
--   * student feedback after each mission (3 smiley questions + an optional comment)
--   * teacher notes per week of the pilot
-- Everything follows the same rules as before: students write only their own rows, teachers read only their classes.

alter table public.events drop constraint if exists events_kind_check;
alter table public.events add constraint events_kind_check check (kind in ('answer','speech','time','step'));
alter table public.events add column if not exists seconds int check (seconds is null or seconds between 0 and 3600);
alter table public.events add column if not exists action text check (action is null or action in ('open','done'));
create index if not exists events_class_kind_item_idx on public.events (class_id, kind, world, activity, item);

create table public.feedback (
  student_id uuid not null references public.students(id) on delete cascade,
  world text not null check (length(world) <= 12),
  activity text not null check (length(activity) <= 24),
  fun smallint check (fun between 1 and 3),
  easy smallint check (easy between 1 and 3),
  learned smallint check (learned between 1 and 3),
  comment text not null default '' check (length(comment) <= 300),
  created_at timestamptz not null default now(),
  primary key (student_id, world, activity)
);
create table public.teacher_notes (
  id bigint generated always as identity primary key,
  class_id uuid not null references public.classes(id) on delete cascade,
  week int not null check (week between 0 and 52),
  note text not null check (length(note) between 1 and 2000),
  created_at timestamptz not null default now()
);
alter table public.feedback enable row level security;
alter table public.teacher_notes enable row level security;
revoke all on public.feedback, public.teacher_notes from anon;
grant select on public.feedback, public.teacher_notes to authenticated;
create policy "teacher: feedback in own classes" on public.feedback for select to authenticated
  using (exists (select 1 from public.students s join public.classes c on c.id = s.class_id where s.id = student_id and c.teacher_id = auth.uid()));
create policy "teacher: notes in own classes" on public.teacher_notes for select to authenticated
  using (exists (select 1 from public.classes c where c.id = class_id and c.teacher_id = auth.uid()));

-- submit_events: also accepts time, step and feedback
create or replace function public.submit_events(p_token text, p_events jsonb) returns int
  language plpgsql security definer set search_path = public, pg_temp as $$
declare s public.students; e jsonb; n int := 0; k text; got int;
begin
  s := public.sq_student(p_token);
  if jsonb_typeof(p_events) <> 'array' or jsonb_array_length(p_events) > 200 then raise exception 'bad_batch' using errcode = 'P0001'; end if;
  for e in select * from jsonb_array_elements(p_events) loop
    k := e->>'kind';
    if k in ('answer','speech','time','step') then
      insert into public.events (student_id, class_id, client_id, kind, world, activity, item, label, correct, first_try, hint, result, seconds, action, client_at)
      values (s.id, s.class_id, left(e->>'id', 64), k, left(coalesce(e->>'world',''),12), left(coalesce(e->>'activity',''),24),
              left(coalesce(e->>'item',''),64), left(coalesce(e->>'label',''),160),
              (e->>'correct')::boolean, (e->>'firstTry')::boolean, (e->>'hint')::boolean,
              case when e->>'result' in ('asr','self','not-yet','skip') then e->>'result' end,
              case when k = 'time' then least(3600, greatest(0, coalesce((e->>'seconds')::int, 0))) end,
              case when e->>'action' in ('open','done') then e->>'action' end,
              least(now(), coalesce((e->>'at')::timestamptz, now())))
      on conflict (student_id, client_id) do nothing;
      get diagnostics got = row_count; n := n + got;
    elsif k = 'progress' then
      insert into public.progress (student_id, world, activity, xp, done, stamps)
      values (s.id, e->>'world', e->>'activity', least(5000, greatest(0, coalesce((e->>'xp')::int,0))), coalesce((e->>'done')::boolean,false), least(200, greatest(0, coalesce((e->>'stamps')::int,0))))
      on conflict (student_id, world, activity) do update
        set xp = greatest(progress.xp, excluded.xp), done = progress.done or excluded.done,
            stamps = greatest(progress.stamps, excluded.stamps), updated_at = now();
      n := n + 1;
    elsif k = 'test' and e->>'test' in ('pre','post') then
      insert into public.tests (student_id, kind, score, total, answers)
      values (s.id, e->>'test', (e->>'score')::int, (e->>'total')::int, coalesce(e->'answers','[]'::jsonb))
      on conflict (student_id, kind) do nothing;
      get diagnostics got = row_count; n := n + got;
    elsif k = 'feedback' then                                   -- the latest answer per mission counts
      insert into public.feedback (student_id, world, activity, fun, easy, learned, comment)
      values (s.id, left(coalesce(e->>'world',''),12), left(coalesce(e->>'activity',''),24),
              nullif((e->>'fun')::int,0), nullif((e->>'easy')::int,0), nullif((e->>'learned')::int,0), left(coalesce(e->>'comment',''),300))
      on conflict (student_id, world, activity) do update set fun = excluded.fun, easy = excluded.easy, learned = excluded.learned, comment = excluded.comment, created_at = now();
      n := n + 1;
    end if;
  end loop;
  update public.students set last_seen = now() where id = s.id;
  return n;
end $$;

-- Everything the pilot tab needs for one class. Weeks count from the class's creation (week 1 = first 7 days).
create or replace function public.pilot_report(p_class uuid) returns jsonb
  language plpgsql stable security definer set search_path = public, pg_temp as $$
declare c public.classes;
begin
  perform public.sq_own_class(p_class);
  select * into c from public.classes where id = p_class;
  return jsonb_build_object(
    'start', c.created_at,
    'time', coalesce((select jsonb_agg(jsonb_build_object('student', x.student_id, 'week', x.week, 'world', x.world, 'activity', x.activity, 'seconds', x.secs)) from (
        select e.student_id, greatest(1, floor(extract(epoch from (coalesce(e.client_at, e.created_at) - c.created_at)) / 604800)::int + 1) as week, e.world, e.activity, sum(e.seconds)::int as secs
          from public.events e where e.class_id = p_class and e.kind = 'time' group by 1,2,3,4) x), '[]'),
    'steps', coalesce((select jsonb_agg(jsonb_build_object('world', x.world, 'activity', x.activity, 'item', x.item, 'opened', x.opened, 'done', x.done)) from (
        select e.world, e.activity, e.item, count(distinct e.student_id) filter (where e.action = 'open') as opened, count(distinct e.student_id) filter (where e.action = 'done') as done
          from public.events e where e.class_id = p_class and e.kind = 'step' group by 1,2,3) x), '[]'),
    'feedback', coalesce((select jsonb_agg(jsonb_build_object('world', f.world, 'activity', f.activity, 'fun', f.fun, 'easy', f.easy, 'learned', f.learned, 'comment', f.comment, 'number', s.number, 'at', f.created_at) order by f.created_at desc)
        from public.feedback f join public.students s on s.id = f.student_id where s.class_id = p_class), '[]'),
    'notes', coalesce((select jsonb_agg(jsonb_build_object('week', n.week, 'note', n.note, 'at', n.created_at) order by n.created_at desc) from public.teacher_notes n where n.class_id = p_class), '[]'));
end $$;

create or replace function public.add_teacher_note(p_class uuid, p_week int, p_note text) returns void
  language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public.sq_own_class(p_class);
  insert into public.teacher_notes (class_id, week, note) values (p_class, p_week, btrim(p_note));
end $$;

-- Raw answers/steps/time for research (CSV export), newest first, at most 20 000 rows.
create or replace function public.pilot_events(p_class uuid) returns jsonb
  language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform public.sq_own_class(p_class);
  return coalesce((select jsonb_agg(jsonb_build_object('number', s.number, 'kind', e.kind, 'world', e.world, 'activity', e.activity, 'item', e.item, 'label', e.label,
           'correct', e.correct, 'firstTry', e.first_try, 'hint', e.hint, 'result', e.result, 'seconds', e.seconds, 'action', e.action, 'at', coalesce(e.client_at, e.created_at)))
    from (select * from public.events where class_id = p_class order by id desc limit 20000) e join public.students s on s.id = e.student_id), '[]');
end $$;

revoke execute on function public.pilot_report(uuid), public.add_teacher_note(uuid,int,text), public.pilot_events(uuid) from public, anon, authenticated;
grant execute on function public.submit_events(text,jsonb) to anon, authenticated;
grant execute on function public.pilot_report(uuid), public.add_teacher_note(uuid,int,text), public.pilot_events(uuid) to authenticated;

-- ================================================================ 20261129000000_worlds.sql
-- SANOR QUEST · Maps 03–06 are playable: new classes open all six worlds (teachers can still close any of them).
alter table public.classes alter column worlds_open set default '{01,02,03,04,05,06}';

-- ================================================================ 20261130000000_launch.sql
-- SANOR QUEST · launch (Phase 9)
--   * coordinators: the project lead(s) who see an anonymous summary across every school (network_report)
--   * client_errors: errors from students' and teachers' browsers, grouped per day (report_error)
--   * ops_keys + health_digest: a secret key lets the scheduled health check (GitHub Actions) read the error
--     summary without a teacher password. Only the key's SHA-256 hash is stored.
-- The cross-school summary has no nicknames, no class numbers and no answers: only counts, averages and
-- pre/post score pairs (percent) per class.

create table public.coordinators (
  id uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
create table public.client_errors (
  day date not null default current_date,
  fingerprint text not null check (fingerprint ~ '^[0-9a-f]{64}$'),
  page text not null default '' check (length(page) <= 80),
  message text not null default '' check (length(message) <= 300),
  source text not null default '' check (length(source) <= 160),
  version text not null default '' check (length(version) <= 24),
  agent text not null default '' check (length(agent) <= 160),
  count int not null default 1 check (count between 1 and 1000000),
  first_at timestamptz not null default now(),
  last_at timestamptz not null default now(),
  primary key (day, fingerprint)
);
create table public.ops_keys (
  key_hash text primary key,
  label text not null default '' check (length(label) <= 60),
  created_at timestamptz not null default now()
);
alter table public.coordinators enable row level security;
alter table public.client_errors enable row level security;
alter table public.ops_keys enable row level security;
revoke all on public.coordinators, public.client_errors, public.ops_keys from anon, authenticated;

create or replace function public.sq_coordinator() returns void
  language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if auth.uid() is null or not exists (select 1 from public.coordinators where id = auth.uid()) then
    raise exception 'not_coordinator' using errcode = 'P0001';
  end if;
end $$;

-- Is the signed-in teacher also a coordinator? (the research page uses this to show or hide itself)
create or replace function public.am_coordinator() returns boolean
  language sql stable security definer set search_path = public, pg_temp as $$
  select auth.uid() is not null and exists (select 1 from public.coordinators where id = auth.uid()) $$;

-- One row per class, grouped by the school name teachers typed when they signed up.
create or replace function public.network_report() returns jsonb
  language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform public.sq_coordinator();
  return coalesce((select jsonb_agg(jsonb_build_object(
      'school', coalesce(nullif(btrim(t.school), ''), '?'),
      'className', c.name,
      'created', c.created_at,
      'students', (select count(*) from public.students s where s.class_id = c.id),
      'active7', (select count(*) from public.students s where s.class_id = c.id and s.last_seen > now() - interval '7 days'),
      'minutes', coalesce((select round(sum(e.seconds) / 60.0) from public.events e where e.class_id = c.id and e.kind = 'time'), 0),
      'answers', (select count(*) from public.events e where e.class_id = c.id and e.kind = 'answer'),
      'firstTry', (select count(*) from public.events e where e.class_id = c.id and e.kind = 'answer' and e.first_try),
      'spoken', (select count(*) from public.events e where e.class_id = c.id and e.kind = 'speech' and e.result in ('asr','self')),
      'done', coalesce((select jsonb_object_agg(x.k, x.n) from (
          select p.world || '/' || p.activity as k, count(*) as n from public.progress p join public.students s on s.id = p.student_id
           where s.class_id = c.id and p.done group by 1) x), '{}'),
      'pre', (select count(*) from public.tests x join public.students s on s.id = x.student_id where s.class_id = c.id and x.kind = 'pre'),
      'post', (select count(*) from public.tests x join public.students s on s.id = x.student_id where s.class_id = c.id and x.kind = 'post'),
      'pairs', coalesce((select jsonb_agg(jsonb_build_array(round(100.0 * a.score / nullif(a.total, 0), 1), round(100.0 * b.score / nullif(b.total, 0), 1)) order by s.number)
          from public.students s join public.tests a on a.student_id = s.id and a.kind = 'pre' join public.tests b on b.student_id = s.id and b.kind = 'post'
         where s.class_id = c.id and a.total > 0 and b.total > 0), '[]'),
      'feedback', (select jsonb_build_object('n', count(*), 'fun', round(avg(f.fun), 2), 'easy', round(avg(f.easy), 2), 'learned', round(avg(f.learned), 2))
          from public.feedback f join public.students s on s.id = f.student_id where s.class_id = c.id)
    ) order by lower(btrim(t.school)), c.name)
    from public.classes c join public.teachers t on t.id = c.teacher_id), '[]');
end $$;

-- Browsers report errors here (no sign-in). Up to 10 per call; identical errors on the same day are counted
-- in one row, and at most 500 different errors are kept per day, so the table cannot be flooded.
create or replace function public.report_error(p_errors jsonb) returns int
  language plpgsql security definer set search_path = public, pg_temp as $$
declare e jsonb; n int := 0; fp text; msg text; pg text; src text;
begin
  if jsonb_typeof(p_errors) <> 'array' or jsonb_array_length(p_errors) > 10 then raise exception 'bad_batch' using errcode = 'P0001'; end if;
  for e in select * from jsonb_array_elements(p_errors) loop
    msg := left(btrim(coalesce(e->>'message', '')), 300); pg := left(coalesce(e->>'page', ''), 80); src := left(coalesce(e->>'source', ''), 160);
    continue when msg = '';
    fp := encode(sha256(convert_to(pg || '|' || msg || '|' || src, 'UTF8')), 'hex');
    update public.client_errors set count = least(count + 1, 1000000), last_at = now(),
           version = left(coalesce(e->>'version', ''), 24), agent = left(coalesce(e->>'agent', ''), 160)
     where day = current_date and fingerprint = fp;
    if not found then
      continue when (select count(*) from public.client_errors where day = current_date) >= 500;
      insert into public.client_errors (fingerprint, page, message, source, version, agent)
      values (fp, pg, msg, src, left(coalesce(e->>'version', ''), 24), left(coalesce(e->>'agent', ''), 160))
      on conflict (day, fingerprint) do update set count = least(client_errors.count + 1, 1000000), last_at = now();
    end if;
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.sq_errors_since(p_since timestamptz) returns jsonb
  language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('page', x.page, 'message', x.message, 'source', x.source, 'version', x.version, 'agent', x.agent,
                                               'count', x.n, 'first', x.f, 'last', x.l) order by x.l desc), '[]')
    from (select page, message, source, max(version) as version, max(agent) as agent, sum(count) as n, min(first_at) as f, max(last_at) as l
            from public.client_errors where last_at > p_since group by page, message, source order by max(last_at) desc limit 100) x $$;

create or replace function public.recent_errors(p_days int) returns jsonb
  language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform public.sq_coordinator();
  return public.sq_errors_since(now() - make_interval(days => least(greatest(coalesce(p_days, 7), 1), 90)));
end $$;

-- For the scheduled health check: errors and activity in the last few hours. Needs the ops key.
create or replace function public.health_digest(p_key text, p_hours int) returns jsonb
  language plpgsql stable security definer set search_path = public, pg_temp as $$
declare since timestamptz := now() - make_interval(hours => least(greatest(coalesce(p_hours, 24), 1), 168));
begin
  if not exists (select 1 from public.ops_keys where key_hash = encode(sha256(convert_to(coalesce(p_key, ''), 'UTF8')), 'hex')) then
    raise exception 'bad_key' using errcode = 'P0001';
  end if;
  return jsonb_build_object('since', since, 'errors', public.sq_errors_since(since),
    'activeStudents', (select count(*) from public.students where last_seen > since),
    'events', (select count(*) from public.events where created_at > since),
    'classes', (select count(*) from public.classes));
end $$;

revoke execute on function public.sq_coordinator(), public.am_coordinator(), public.network_report(), public.report_error(jsonb),
  public.sq_errors_since(timestamptz), public.recent_errors(int), public.health_digest(text,int) from public, anon, authenticated;
grant execute on function public.report_error(jsonb), public.health_digest(text,int) to anon, authenticated;
grant execute on function public.am_coordinator(), public.network_report(), public.recent_errors(int) to authenticated;
